import sys,numpy as np
sys.path[:0]=['/app/output','/opt/tools']
import rcb_dtb as rcb
from gen import Builder
A=np.load('/app/output/trajectory.npz')['actions']
for scale in [.7,.9,1.0,1.1,1.2,1.4,1.7,2.0]:
 s=rcb.Session('/app/instance.json');
 for row in A:s.step(row)
 b=Builder(s)
 def move(k,sc,n=50):
  po=s.state()['object_pos'];pp,qp=b.palm_pose();d=np.asarray(s.goals[k][:3])-po;q=b.ik(pp+sc*d,qp);start=b.last.copy();dq=q-start[:7];best=(9,0);before=s.goal_index
  for j in range(1,n+1):
   u=j/n;u=u*u*(3-2*u);cmd=start.copy();cmd[:7]=start[:7]+u*dq;b.send(cmd);dist=s.progress()['goal_distance_m'];
   if dist<best[0]:best=(dist,j)
   if s.goal_index!=before:break
  return best,j
 move(1,1.1,50)
 if s.goal_index==2:
  best,j=move(2,scale,80)
  print(scale,'index',s.goal_index,'best',best,'steps',j,'final',s.progress()['goal_distance_m'],flush=True)
 else: print(scale,'failed first',s.goal_index,flush=True)
